def runMaxQueue(ops):
    from collections import deque
    q = deque()
    best = deque()
    out = []
    for t, x in ops:
        if t == 1:
            q.append(x)
            while best and best[-1] < x:
                best.pop()
            best.append(x)
        elif t == 2:
            v = q.popleft()
            if best[0] == v:
                best.popleft()
        else:
            out.append(best[0])
    return out
